1. using Microsoft.VisualStudio.TestTools.UnitTesting;
2. using Store;
3. 
4. namespace Store.Tests;
5. 
6. [TestClass]
7. public class ShoppingCartTests
8. {
9.     private ShoppingCart _cart = null!;
10. 
11.     [TestInitialize]
12.     public void Setup()
13.     {
14.         _cart = new ShoppingCart();
15.     }
16. 
17.     // --- AddItem Tests ---
18. 
19.     [TestMethod]
20.     public void AddItem_SingleItem_IncreasesTotal()
21.     {
22.         _cart.AddItem("SKU-001", 2, 9.99m);
23. 
24.         Assert.AreEqual(19.98m, _cart.CalculateTotal());
25.     }
26. 
27.     [TestMethod]
28.     public void AddItem_MultipleDistinctItems_SumsCorrectly()
29.     {
30.         _cart.AddItem("SKU-001", 1, 10.00m);
31.         _cart.AddItem("SKU-002", 3, 5.00m);
32. 
33.         Assert.AreEqual(25.00m, _cart.CalculateTotal());
34.     }
35. 
36.     [TestMethod]
37.     public void AddItem_SameSkuTwice_AccumulatesQuantity()
38.     {
39.         _cart.AddItem("SKU-001", 1, 10.00m);
40.         _cart.AddItem("SKU-001", 2, 10.00m);
41. 
42.         Assert.AreEqual(30.00m, _cart.CalculateTotal());
43.     }
44. 
45.     [TestMethod]
46.     public void AddItem_ZeroQuantity_ThrowsArgumentException()
47.     {
48.         Assert.ThrowsExactly<ArgumentException>(() =>
49.             _cart.AddItem("SKU-001", 0, 10.00m));
50.     }
51. 
52.     [TestMethod]
53.     public void AddItem_NegativePrice_ThrowsArgumentException()
